    'float': 'float', 'int': 'int', 'bool': 'bool',
    'complex': 'complex', 'object': 'object', 'str': 'str',
    'unicode': 'str', 'long': 'int'
}
for p in files:
    old = p.read_text()
    new = old
    for alias in ('np', 'n', 'numpy'):
        for name, replacement in repls.items():
            new = re.sub(r'(?<![A-Za-z0-9_])' + alias + r'\.' + name + r'(?![A-Za-z0-9_])', replacement, new)
    if new != old:
        p.write_text(new)
        print('patched', p)
