import planarity
from pyknotid.representations.representation import Representation
# Use a valid compact Gauss code form accepted by this version.
for text in ('1+a,2-a,3+a,1-a,2+a,3-a', '1+a 2-a 3+a 1-a 2+a 3-a'):
    try:
        r = Representation(text)
        print('accepted', repr(text), type(r))
        break
    except Exception as e:
        print('rejected', repr(text), repr(e))
else:
    raise SystemExit
try:
    pd = r.planar_diagram()
    g, duplicates, heights, first_edge = pd.as_networkx_extended()
    print('original nodes:', list(g.nodes(data=True))[:12])
    original = {x: dict(d) for x, d in g.nodes(data=True)}
    pg = planarity.PGraph(g)
    print('mapping:', getattr(pg, 'mapping', None))
    pg.embed_drawplanar()
    gg = planarity.networkx_graph(pg)
    print('converted nodes:', list(gg.nodes(data=True))[:12])
except Exception as e:
    import traceback; traceback.print_exc()
